1	// Package store persists document change batches in a SQLite database.
2	//
3	// Within a document every change has a client-supplied id. New ids receive a
4	// monotonically increasing cursor; re-posting an existing id is idempotent
5	// only when the deviceId and decoded JSON payload match, otherwise it is a
6	// conflict. Valid batches commit atomically, so cursors never repeat and no
7	// record is partially written, even under concurrent writers.
8	//
9	// A document may also carry snapshots: caller-supplied JSON states pinned to
10	// existing change cursors. Snapshots are write-once per cursor — a matching
11	// re-post is idempotent, a differing one a conflict — and live apart from the
12	// change log.
13	package store
14	
15	import (
16		"database/sql"
17		"encoding/json"
18		"errors"
19		"fmt"
20	
21		_ "modernc.org/sqlite"
22	)
23	
24	// ErrStaleCursor reports that a merge targets a base cursor for an unknown
25	// document, or a base cursor greater than the document's current cursor. The
26	// caller maps it to 400; nothing is written.
27	var ErrStaleCursor = errors.New("baseCursor is unknown or ahead of the current cursor")
28	
29	// Change is one element of an inbound batch or one row of a listing.
30	type Change struct {
31		ID       string          // client-supplied change id, unique per document
32		DeviceID string          // originating device
33		Payload  json.RawMessage // decoded JSON value, stored verbatim
34	}
35	
36	// Result reports the outcome for one element of an accepted batch.
37	type Result struct {
38		ID      string `json:"id"`
39		Created bool   `json:"created"`
40		Cursor  int64  `json:"cursor"`
41	}
42	
43	// ListedChange is one row in a ListChanges response.
44	type ListedChange struct {
45		ID       string          `json:"id"`
46		DeviceID string          `json:"deviceId"`
47		Payload  json.RawMessage `json:"payload"`
48		Cursor   int64           `json:"cursor"`
49	}
50	
51	// MergeResult reports the outcome of an accepted MergeChange. Outcome is one
52	// of "idempotent", "applied" or "merged".
53	type MergeResult struct {
54		ID      string  `json:"id"`
55		Outcome string  `json:"outcome"`
56		Cursor  int64   `json:"cursor"`
57		Result  *Result `json:"result,omitempty"`
58	}
59	
60	// ErrConflict reports that a batch references an existing change id with a
61	// different deviceId or payload. The whole batch is rejected.
62	type ErrConflict struct {
63		ID string
64	}
65	
66	func (e *ErrConflict) Error() string {
67		return fmt.Sprintf("conflicting change %q for document", e.ID)
68	}
69	
70	// ErrSnapshotBase reports that a snapshot targets an unknown document or a
71	// cursor that is not an existing change cursor of the document. The caller
72	// maps it to 400; nothing is written.
73	var ErrSnapshotBase = errors.New("snapshot cursor is not an existing cursor of the document")
74	
75	// ErrSnapshotNotFound reports that no snapshot exists for the document and
76	// cursor. The caller maps it to 404.
77	var ErrSnapshotNotFound = errors.New("snapshot not found")
78	
79	// ErrSnapshotConflict reports that a snapshot already exists for the document
80	// and cursor with a different state. The stored snapshot is left unchanged.
81	type ErrSnapshotConflict struct {
82		Cursor int64
83	}
84	
85	func (e *ErrSnapshotConflict) Error() string {
86		return fmt.Sprintf("conflicting snapshot for cursor %d", e.Cursor)
87	}
88	
89	// Store is the durable change log.
90	type Store struct {
91		db *sql.DB
92	}
93	
94	// Open opens (creating if needed) the SQLite database at path. The empty path
95	// opens an in-memory database useful for tests.
96	func Open(path string) (*Store, error) {
97		if path == "" {
98			// With a single pooled connection this is a private, per-instance
99			// in-memory database (useful for tests).
100			path = "file::memory:"
101		}
102		// _txlock=immediate makes writers acquire the write lock at BEGIN, so
103		// concurrent batches serialize without SQLITE_BUSY deadlocks.
104		dsn := path + "?_txlock=immediate&_busy_timeout=5000&_journal_mode=WAL&_synchronous=FULL&_foreign_keys=on"
105		db, err := sql.Open("sqlite", dsn)
106		if err != nil {
107			return nil, err
108		}
109		// One connection avoids cross-connection locking surprises; writes are
110		// serialized by the immediate transaction anyway, and SQLite concurrency
111		// for readers does not help correctness here.
112		db.SetMaxOpenConns(1)
113		s := &Store{db: db}
114		if err := s.init(); err != nil {
115			_ = db.Close()
116			return nil, err
117		}
118		return s, nil
119	}
120	
121	func (s *Store) init() error {
122		_, err := s.db.Exec(`
123	CREATE TABLE IF NOT EXISTS changes (
124		document_id TEXT NOT NULL,
125		cursor      INTEGER NOT NULL,
126		id          TEXT NOT NULL,
127		device_id   TEXT NOT NULL,
128		payload     BLOB NOT NULL,
129		PRIMARY KEY (document_id, id)
130	);
131	CREATE UNIQUE INDEX IF NOT EXISTS changes_doc_cursor_idx
132		ON changes(document_id, cursor);
133	CREATE TABLE IF NOT EXISTS snapshots (
134		document_id TEXT NOT NULL,
135		cursor      INTEGER NOT NULL,
136		state       BLOB NOT NULL,
137		PRIMARY KEY (document_id, cursor)
138	);
139	`)
140		return err
141	}
142	
143	// Close releases the database handle.
144	func (s *Store) Close() error { return s.db.Close() }
145	
146	// PostChanges validates and commits one batch atomically.
147	//
148	// Every change must have a non-empty id; duplicate ids within the batch are
149	// rejected by the caller before reaching this point. On conflict the returned
150	// error is *ErrConflict and nothing is written. Cursors are assigned in batch
151	// order to ids that do not yet exist. Results are returned in the same order
152	// as the input.
153	func (s *Store) PostChanges(documentID string, changes []Change) ([]Result, error) {
154		tx, err := s.db.Begin()
155		if err != nil {
156			return nil, err
157		}
158		defer func() { _ = tx.Rollback() }()
159	
160		results := make([]Result, len(changes))
161	
162		// First pass: resolve every id against existing rows. A single mismatch
163		// aborts the whole batch before any cursor is allocated.
164		pending := make([]int, 0, len(changes))
165		for i, c := range changes {
166			var existingDevice string
167			var existingPayload []byte
168			var existingCursor int64
169			err := tx.QueryRow(
170				`SELECT cursor, device_id, payload FROM changes WHERE document_id = ? AND id = ?`,
171				documentID, c.ID,
172			).Scan(&existingCursor, &existingDevice, &existingPayload)
173			switch {
174			case errors.Is(err, sql.ErrNoRows):
175				pending = append(pending, i)
176			case err != nil:
177				return nil, err
178			default:
179				if existingDevice != c.DeviceID || !jsonEqual(existingPayload, c.Payload) {
180					return nil, &ErrConflict{ID: c.ID}
181				}
182				results[i] = Result{
183					ID:      c.ID,
184					Created: false,
185					Cursor:  existingCursor,
186				}
187			}
188		}
189	
190		// Allocate cursors for genuinely new ids.
191		var nextCursor int64
192		if err := tx.QueryRow(
193			`SELECT COALESCE(MAX(cursor), 0) + 1 FROM changes WHERE document_id = ?`,
194			documentID,
195		).Scan(&nextCursor); err != nil {
196			return nil, err
197		}
198		for _, i := range pending {
199			c := changes[i]
200			if _, err := tx.Exec(
201				`INSERT INTO changes (document_id, cursor, id, device_id, payload) VALUES (?, ?, ?, ?, ?)`,
202				documentID, nextCursor, c.ID, c.DeviceID, []byte(c.Payload),
203			); err != nil {
204				return nil, err
205			}
206			results[i] = Result{
207				ID:      c.ID,
208				Created: true,
209				Cursor:  nextCursor,
210			}
211			nextCursor++
212		}
213	
214		if err := tx.Commit(); err != nil {
215			return nil, err
216		}
217		return results, nil
218	}
219	
220	// MergeChange validates and appends one change against a caller-observed base
221	// cursor, all within a single serialized transaction.
222	//
223	//   - An existing id is idempotent only when deviceId and the decoded payload
224	//     match (Outcome "idempotent", with the original Result); a mismatch is an
225	//     *ErrConflict and nothing is written.
226	//   - A new id with baseCursor equal to the current cursor is appended as
227	//     "applied".
228	//   - A new id with a base cursor behind the current one is appended as
229	//     "merged" only when every change after baseCursor carries a JSON object
230	//     payload whose top-level keys are disjoint from the new payload's; any
231	//     non-object later payload or shared key is an *ErrConflict.
232	//
233	// A non-zero baseCursor for an unknown document, or a baseCursor greater than
234	// the current cursor, returns ErrStaleCursor. An unknown document with
235	// baseCursor 0 accepts the first change as "applied".
236	func (s *Store) MergeChange(documentID string, baseCursor int64, c Change) (MergeResult, error) {
237		tx, err := s.db.Begin()
238		if err != nil {
239			return MergeResult{}, err
240		}
241		defer func() { _ = tx.Rollback() }()
242	
243		// Current cursor is the document's high-water mark, 0 when unknown.
244		var current int64
245		if err := tx.QueryRow(
246			`SELECT COALESCE(MAX(cursor), 0) FROM changes WHERE document_id = ?`,
247			documentID,
248		).Scan(&current); err != nil {
249			return MergeResult{}, err
250		}
251		if baseCursor > current || (baseCursor != 0 && current == 0) {
252			return MergeResult{}, ErrStaleCursor
253		}
254	
255		// An existing id keeps the original idempotency/conflict rules.
256		var existingDevice string
257		var existingPayload []byte
258		var existingCursor int64
259		err = tx.QueryRow(
260			`SELECT cursor, device_id, payload FROM changes WHERE document_id = ? AND id = ?`,
261			documentID, c.ID,
262		).Scan(&existingCursor, &existingDevice, &existingPayload)
263		switch {
264		case errors.Is(err, sql.ErrNoRows):
265			// New id; fall through to append logic below.
266		case err != nil:
267			return MergeResult{}, err
268		default:
269			if existingDevice != c.DeviceID || !jsonEqual(existingPayload, c.Payload) {
270				return MergeResult{}, &ErrConflict{ID: c.ID}
271			}
272			return MergeResult{
273				ID:      c.ID,
274				Outcome: "idempotent",
275				Cursor:  existingCursor,
276				Result: &Result{
277					ID:      c.ID,
278					Created: false,
279					Cursor:  existingCursor,
280				},
281			}, nil
282		}
283	
284		outcome := "applied"
285		if baseCursor < current {
286			// Merge is allowed only when every change after baseCursor is a JSON
287			// object whose top-level keys do not collide with the new payload's.
288			newKeys, err := objectKeys(c.Payload)
289			if err != nil {
290				if errors.Is(err, errNotObject) {
291					return MergeResult{}, &ErrConflict{ID: c.ID}
292				}
293				return MergeResult{}, err
294			}
295			rows, err := tx.Query(
296				`SELECT payload FROM changes
297				 WHERE document_id = ? AND cursor > ?
298				 ORDER BY cursor ASC`,
299				documentID, baseCursor,
300			)
301			if err != nil {
302				return MergeResult{}, err
303			}
304			for rows.Next() {
305				var laterPayload []byte
306				if err := rows.Scan(&laterPayload); err != nil {
307					_ = rows.Close()
308					return MergeResult{}, err
309				}
310				laterKeys, err := objectKeys(laterPayload)
311				if err != nil {
312					_ = rows.Close()
313					if errors.Is(err, errNotObject) {
314						return MergeResult{}, &ErrConflict{ID: c.ID}
315					}
316					return MergeResult{}, err
317				}
318				for k := range newKeys {
319					if _, clash := laterKeys[k]; clash {
320						_ = rows.Close()
321						return MergeResult{}, &ErrConflict{ID: c.ID}
322					}
323				}
324			}
325			if err := rows.Err(); err != nil {
326				_ = rows.Close()
327				return MergeResult{}, err
328			}
329			_ = rows.Close()
330			outcome = "merged"
331		}
332	
333		next := current + 1
334		if _, err := tx.Exec(
335			`INSERT INTO changes (document_id, cursor, id, device_id, payload) VALUES (?, ?, ?, ?, ?)`,
336			documentID, next, c.ID, c.DeviceID, []byte(c.Payload),
337		); err != nil {
338			return MergeResult{}, err
339		}
340	
341		if err := tx.Commit(); err != nil {
342			return MergeResult{}, err
343		}
344		return MergeResult{ID: c.ID, Outcome: outcome, Cursor: next}, nil
345	}
346	
347	// PutSnapshot stores state as the snapshot of documentID at cursor, creating
348	// it on first use and reporting whether this call created it.
349	//
350	// Only cursors of existing changes are valid snapshot points: an unknown
351	// document, a cursor below 1 or a cursor ahead of the document's current
352	// cursor yields ErrSnapshotBase and nothing is written. Re-posting a state
353	// that decodes equal to the stored one is idempotent (created=false); a
354	// different state is an *ErrSnapshotConflict and the stored snapshot is left
355	// unchanged. Snapshots are independent of the change log: they neither move
356	// the document's cursor nor affect merges.
357	func (s *Store) PutSnapshot(documentID string, cursor int64, state json.RawMessage) (bool, error) {
358		tx, err := s.db.Begin()
359		if err != nil {
360			return false, err
361		}
362		defer func() { _ = tx.Rollback() }()
363	
364		var current int64
365		if err := tx.QueryRow(
366			`SELECT COALESCE(MAX(cursor), 0) FROM changes WHERE document_id = ?`,
367			documentID,
368		).Scan(&current); err != nil {
369			return false, err
370		}
371		if current == 0 || cursor < 1 || cursor > current {
372			return false, ErrSnapshotBase
373		}
374	
375		var existing []byte
376		err = tx.QueryRow(
377			`SELECT state FROM snapshots WHERE document_id = ? AND cursor = ?`,
378			documentID, cursor,
379		).Scan(&existing)
380		switch {
381		case errors.Is(err, sql.ErrNoRows):
382			if _, err := tx.Exec(
383				`INSERT INTO snapshots (document_id, cursor, state) VALUES (?, ?, ?)`,
384				documentID, cursor, []byte(state),
385			); err != nil {
386				return false, err
387			}
388			if err := tx.Commit(); err != nil {
389				return false, err
390			}
391			return true, nil
392		case err != nil:
393			return false, err
394		default:
395			if !jsonEqual(existing, state) {
396				return false, &ErrSnapshotConflict{Cursor: cursor}
397			}
398			return false, nil
399		}
400	}
401	
402	// GetSnapshot returns the state stored for documentID at cursor. Any miss —
403	// unknown document, unknown cursor or absent snapshot — yields
404	// ErrSnapshotNotFound.
405	func (s *Store) GetSnapshot(documentID string, cursor int64) (json.RawMessage, error) {
406		var state []byte
407		err := s.db.QueryRow(
408			`SELECT state FROM snapshots WHERE document_id = ? AND cursor = ?`,
409			documentID, cursor,
410		).Scan(&state)
411		switch {
412		case errors.Is(err, sql.ErrNoRows):
413			return nil, ErrSnapshotNotFound
414		case err != nil:
415			return nil, err
416		default:
417			return json.RawMessage(state), nil
418		}
419	}
420	
421	// errNotObject marks a payload that is not a JSON object.
422	var errNotObject = errors.New("payload is not a JSON object")
423	
424	// objectKeys returns the top-level keys of a JSON object payload. A null,
425	// array or scalar payload yields errNotObject.
426	func objectKeys(raw json.RawMessage) (map[string]struct{}, error) {
427		var m map[string]json.RawMessage
428		if err := json.Unmarshal(raw, &m); err != nil {
429			// Valid JSON that is not an object (array, scalar, null) decodes with
430			// a type error into a map; treat it and malformed JSON as non-object.
431			return nil, errNotObject
432		}
433		if m == nil {
434			return nil, errNotObject
435		}
436		keys := make(map[string]struct{}, len(m))
437		for k := range m {
438			keys[k] = struct{}{}
439		}
440		return keys, nil
441	}
442	
443	// ListChanges returns at most limit changes for documentID whose cursor is
444	// greater than after, in cursor order, together with the cursor to pass as
445	// the next after value. An unknown document yields an empty list and cursor 0;
446	// a known document with no rows past after yields nextCursor == after.
447	func (s *Store) ListChanges(documentID string, after, limit int64) ([]ListedChange, int64, error) {
448		rows, err := s.db.Query(
449			`SELECT id, device_id, payload, cursor FROM changes
450			 WHERE document_id = ? AND cursor > ?
451			 ORDER BY cursor ASC
452			 LIMIT ?`,
453			documentID, after, limit,
454		)
455		if err != nil {
456			return nil, 0, err
457		}
458		defer func() { _ = rows.Close() }()
459	
460		out := make([]ListedChange, 0)
461		var maxCursor int64 = after
462		for rows.Next() {
463			var c ListedChange
464			if err := rows.Scan(&c.ID, &c.DeviceID, &c.Payload, &c.Cursor); err != nil {
465				return nil, 0, err
466			}
467			out = append(out, c)
468			maxCursor = c.Cursor
469		}
470		if err := rows.Err(); err != nil {
471			return nil, 0, err
472		}
473	
474		// Distinguish an unknown document from a known one with nothing new:
475		// unknown documents must report nextCursor 0.
476		if len(out) == 0 {
477			var known bool
478			if err := s.db.QueryRow(
479				`SELECT EXISTS(SELECT 1 FROM changes WHERE document_id = ?)`,
480				documentID,
481			).Scan(&known); err != nil {
482				return nil, 0, err
483			}
484			if !known {
485				return out, 0, nil
486			}
487		}
488		return out, maxCursor, nil
489	}
490	
491	// jsonEqual reports whether two payloads are equal after JSON decoding, so
492	// 1 and 1.0, or {"a":1,"b":2} and {"b":2,"a":1}, compare equal.
493	func jsonEqual(a, b json.RawMessage) bool {
494		var va, vb any
495		if err := json.Unmarshal(a, &va); err != nil {
496			return false
497		}
498		if err := json.Unmarshal(b, &vb); err != nil {
499			return false
500		}
501		return deepEqual(va, vb)
502	}
503	
504	func deepEqual(a, b any) bool {
505		switch av := a.(type) {
506		case nil:
507			return b == nil
508		case bool:
509			bv, ok := b.(bool)
510			return ok && av == bv
511		case string:
512			bv, ok := b.(string)
513			return ok && av == bv
514		case float64:
515			bv, ok := b.(float64)
516			return ok && av == bv
517		case []any:
518			bv, ok := b.([]any)
519			if !ok || len(av) != len(bv) {
520				return false
521			}
522			for i := range av {
523				if !deepEqual(av[i], bv[i]) {
524					return false
525				}
526			}
527			return true
528		case map[string]any:
529			bv, ok := b.(map[string]any)
530			if !ok || len(av) != len(bv) {
531				return false
532			}
533			for k, v := range av {
534				w, exists := bv[k]
535				if !exists || !deepEqual(v, w) {
536					return false
537				}
538			}
539			return true
540		default:
541			return false
542		}
543	}
