	if w.Code != 200 {
		t.Fatal(w.Body.String())
	}
	// A rejected merge (baseCursor ahead) must not write.
	w, _ = mergeBody(t, h, "doc", map[string]any{
		"deviceId": "dev", "baseCursor": 5,
		"change": map[string]any{"id": "ghost-change", "payload": map[string]any{"x": 1}},
