625			t.Fatalf("unknown doc err = %v", err)
626		}
627		if _, err := s.PostChanges("doc", changes("c1")); err != nil {
628			t.Fatal(err)
629		}
630		if _, err := s.GetSnapshot("doc", 1); !errors.Is(err, ErrSnapshotNotFound) {
631			t.Fatalf("known doc without snapshot err = %v", err)
632		}
633	}
