661		}
662	
663		// Idempotency and conflict decisions survive the restart.
664		created, err := s2.PutSnapshot("doc", 1, json.RawMessage(`{"a":1}`))
665		if err != nil || created {
666			t.Fatalf("retry after reopen = created:%v err:%v", created, err)
667		}
668		var conflict *ErrSnapshotConflict
669		if _, err := s2.PutSnapshot("doc", 1, json.RawMessage(`{"a":9}`)); !errors.As(err, &conflict) {
670			t.Fatalf("conflict after reopen err = %v", err)
671		}
672	
673		// Snapshots do not move the change log.
674		rows, next, err := s2.ListChanges("doc", 0, 100)
675		if err != nil || len(rows) != 2 || next != 2 {
676			t.Fatalf("changes after snapshots = %+v next=%d err=%v", rows, next, err)
