func TestSnapshotConcurrentPuts(t *testing.T) {
	s, err := Open("")
	if err != nil {
		t.Fatal(err)
	}
	defer func() { _ = s.Close() }()

	if _, err := s.PostChanges("doc", changes("c1")); err != nil {
		t.Fatal(err)
	}

	// Concurrent identical puts: exactly one creator, no errors.
	var wg sync.WaitGroup
	var mu sync.Mutex
	creators := 0
	for i := 0; i < 8; i++ {
