	for i := 0; i < 8; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			created, err := s.PutSnapshot("doc", 1, json.RawMessage(`{"v":1}`))
			if err != nil {
				t.Error(err)
				return
			}
			if created {
				mu.Lock()
				creators++
				mu.Unlock()
			}
		}()
	}
	wg.Wait()
	if creators != 1 {
		t.Fatalf("creators = %d, want 1", creators)
	}
}

func TestRestoreAppendsSnapshotState(t *testing.T) {
